#!/usr/bin/env python3
"""Generated by stone render. Do not edit: change .cornerstone/config.yaml and render again.

Context guard hook (D115). It never fails the session: any error or a timeout exits with code 0 and
no output. Two events:
- UserPromptSubmit: read the context size of the last call from the transcript. If it passes LIMIT,
  add one message for the agent, once for each BAND tokens over the limit.
- PostToolUse after a PR is opened: add one message to finish the ticket and start the next in a new session.
"""

import json
import os
import re
import signal
import sys
import tempfile

LIMIT = 150000
BAND = 50000
TAIL_BYTES = 1 << 20  # read only the end of the transcript
SECONDS = 4  # the settings entry stops the hook at 5 seconds
PR_COMMAND = re.compile(r"\bgh\s+pr\s+create\b")


def size_message(size: int) -> str:
    return (f"Context guard: the session context is {size} tokens. The limit is {LIMIT}. "
            "Tell the user this size now. Suggest a compact, or a new session.")


PR_MESSAGE = ("Context guard: a PR is open. Finish this ticket. Start the next ticket in a new session.")


def context_size(path: str) -> int | None:
    """Return the input tokens of the last main-thread call in the transcript, or None."""
    with open(path, "rb") as handle:
        handle.seek(0, os.SEEK_END)
        end = handle.tell()
        handle.seek(max(0, end - TAIL_BYTES))
        lines = handle.read().decode("utf-8", errors="replace").splitlines()
    for line in reversed(lines):
        try:
            entry = json.loads(line)
            usage = entry["message"]["usage"]
            if entry.get("isSidechain") or entry.get("type") != "assistant":
                continue
            return sum(int(usage.get(name) or 0) for name in
                       ("input_tokens", "cache_read_input_tokens", "cache_creation_input_tokens"))
        except (ValueError, KeyError, TypeError, AttributeError):
            continue  # a partial first line, or a line with no usage
    return None


def state_path(session: str) -> str:
    return os.path.join(tempfile.gettempdir(), "stone-context-guard-" + re.sub(r"[^A-Za-z0-9_-]", "_", session))


def reset(session: str) -> None:
    try:
        os.remove(state_path(session))
    except OSError:
        pass


def next_band(session: str, size: int) -> bool:
    """Return True once for each band over the limit. Record the band in the state file."""
    band = (size - LIMIT) // BAND
    path = state_path(session)
    try:
        with open(path, encoding="utf-8") as handle:
            last = int(handle.read().strip())
    except (OSError, ValueError):
        last = -1
    if band <= last:
        return False
    with open(path, "w", encoding="utf-8") as handle:
        handle.write(str(band))
    return True


def opened_pr(event: dict) -> bool:
    tool = str(event.get("tool_name") or "")
    command = str((event.get("tool_input") or {}).get("command") or "")
    return (tool == "Bash" and PR_COMMAND.search(command) is not None) or tool.endswith("create_pull_request")


def message(event: dict) -> str:
    name = event.get("hook_event_name")
    if name == "PostToolUse":
        return PR_MESSAGE if opened_pr(event) else ""
    path = event.get("transcript_path")
    if name != "UserPromptSubmit" or not path or LIMIT < 1:
        return ""
    size = context_size(path)
    if size is None:
        return ""
    if size <= LIMIT:
        reset(str(event.get("session_id") or "none"))  # a compaction starts the bands again
        return ""
    return size_message(size) if next_band(str(event.get("session_id") or "none"), size) else ""


def main() -> None:
    event = json.load(sys.stdin)
    text = message(event)
    if text:
        print(json.dumps({"hookSpecificOutput": {"hookEventName": event["hook_event_name"],
                                                 "additionalContext": text}}))


def stop(*_: object) -> None:
    os._exit(0)


if __name__ == "__main__":
    try:
        if hasattr(signal, "SIGALRM"):
            signal.signal(signal.SIGALRM, stop)
            signal.alarm(SECONDS)
        main()
    except BaseException:  # the guard must never fail the session
        pass
    sys.exit(0)
